INSERT INTO `t_pokemon` (`number`,`name`,`name_en`,`category`,`category2`,`level`,`classification`,`height`,`weight`,`description`,`image`,`detail_json`) VALUES
('001','妙蛙种子','Bulbasaur','草','毒','普通','种子宝可梦','0.7m','6.9kg','背上的种子与它共生，晒足阳光便会更加茁壮。小智的妙蛙种子性格沉稳，长大后负责守护大木研究所后山的妙蛙花园，是伙伴们心中的「大哥」。','/pokemon/001.png','{"id":1,"number":"001","name":"妙蛙种子","nameEn":"Bulbasaur","category":"草","category2":"毒","level":"普通","classification":"种子宝可梦","height":"0.7m","weight":"6.9kg","description":"背上的种子与它共生，晒足阳光便会更加茁壮。小智的妙蛙种子性格沉稳，长大后负责守护大木研究所后山的妙蛙花园，是伙伴们心中的「大哥」。","image":"/pokemon/001.png","region":"关都","rarity":"普通","stats":{"hp":45,"atk":49,"def":49,"spa":65,"spd":65,"spe":45},"ability":"茂盛","hidden":"叶绿素","egg":["—"],"steps":0,"evo":["妙蛙种子","妙蛙草","妙蛙花"],"forms":["关都形态"],"signature":"茂盛"}'),
('002','妙蛙草','Ivysaur','草','毒','稀有','种子宝可梦','1m','13kg','「妙蛙草」是关都地区的种子宝可梦，草／毒属性，特性为「茂盛」。','https://assets.pokemon.com/assets/cms2/img/pokedex/full/002.png','{"id":2,"number":"002","name":"妙蛙草","nameEn":"Ivysaur","category":"草","category2":"毒","level":"稀有","classification":"种子宝可梦","height":"1m","weight":"13kg","description":"「妙蛙草」是关都地区的种子宝可梦，草／毒属性，特性为「茂盛」。","image":"https://assets.pokemon.com/assets/cms2/img/pokedex/full/002.png","region":"关都","rarity":"稀有","stats":{"hp":60,"atk":62,"def":63,"spa":80,"spd":80,"spe":60},"ability":"茂盛","hidden":"叶绿素","egg":["—"],"steps":0,"evo":["妙蛙种子","妙蛙草","妙蛙花"],"forms":["关都形态"],"signature":"茂盛"}'),
('003','妙蛙花','Venusaur','草','毒','史诗','花朵宝可梦','2.0m','100.0kg','妙蛙种子的最终进化型，背上的花朵盛开时会散发抚慰心灵的香气，并靠吸收阳光补充能量。在妙蛙花园中是被众多种子宝可梦围绕的守护者。','/pokemon/003.png','{"id":3,"number":"003","name":"妙蛙花","nameEn":"Venusaur","category":"草","category2":"毒","level":"史诗","classification":"花朵宝可梦","height":"2.0m","weight":"100.0kg","description":"妙蛙种子的最终进化型，背上的花朵盛开时会散发抚慰心灵的香气，并靠吸收阳光补充能量。在妙蛙花园中是被众多种子宝可梦围绕的守护者。","image":"/pokemon/003.png","region":"关都","rarity":"史诗","stats":{"hp":80,"atk":82,"def":83,"spa":100,"spd":100,"spe":80},"ability":"茂盛","hidden":"叶绿素","egg":["—"],"steps":0,"evo":["妙蛙草","妙蛙花"],"forms":["关都形态"],"signature":"茂盛"}'),
('004','小火龙','Charmander','火','','普通','蜥蜴宝可梦','0.6m','8.5kg','尾巴尖燃烧着代表生命的火焰。小智在暴雨中救下被原主人遗弃、尾巴将熄的小火龙，此后它一路进化为火恐龙与喷火龙，成为小智最可靠的空中战力。','/pokemon/004.png','{"id":4,"number":"004","name":"小火龙","nameEn":"Charmander","category":"火","category2":null,"level":"普通","classification":"蜥蜴宝可梦","height":"0.6m","weight":"8.5kg","description":"尾巴尖燃烧着代表生命的火焰。小智在暴雨中救下被原主人遗弃、尾巴将熄的小火龙，此后它一路进化为火恐龙与喷火龙，成为小智最可靠的空中战力。","image":"/pokemon/004.png","region":"关都","rarity":"普通","stats":{"hp":39,"atk":52,"def":43,"spa":60,"spd":50,"spe":65},"ability":"猛火","hidden":"太阳之力","egg":["—"],"steps":0,"evo":["小火龙","火恐龙","喷火龙"],"forms":["关都形态"],"signature":"猛火"}'),
('005','火恐龙','Charmeleon','火','','稀有','火焰宝可梦','1.1m','19kg','「火恐龙」是关都地区的火焰宝可梦，火属性，特性为「猛火」。','https://assets.pokemon.com/assets/cms2/img/pokedex/full/005.png','{"id":5,"number":"005","name":"火恐龙","nameEn":"Charmeleon","category":"火","category2":null,"level":"稀有","classification":"火焰宝可梦","height":"1.1m","weight":"19kg","description":"「火恐龙」是关都地区的火焰宝可梦，火属性，特性为「猛火」。","image":"https://assets.pokemon.com/assets/cms2/img/pokedex/full/005.png","region":"关都","rarity":"稀有","stats":{"hp":58,"atk":64,"def":58,"spa":80,"spd":65,"spe":80},"ability":"猛火","hidden":"太阳之力","egg":["—"],"steps":0,"evo":["小火龙","火恐龙","喷火龙"],"forms":["关都形态"],"signature":"猛火"}'),
('006','喷火龙','Charizard','火','飞行','传说','火焰宝可梦','1.7m','90.5kg','小火龙的最终进化型，双翼内侧泛着青蓝色。曾因骄傲不听话，在喷火龙山谷修行归来后彻底蜕变，橘子群岛一战击败传说宝可梦急冻鸟，成为小智最强大的伙伴之一。','/pokemon/006.png','{"id":6,"number":"006","name":"喷火龙","nameEn":"Charizard","category":"火","category2":"飞行","level":"传说","classification":"火焰宝可梦","height":"1.7m","weight":"90.5kg","description":"小火龙的最终进化型，双翼内侧泛着青蓝色。曾因骄傲不听话，在喷火龙山谷修行归来后彻底蜕变，橘子群岛一战击败传说宝可梦急冻鸟，成为小智最强大的伙伴之一。","image":"/pokemon/006.png","region":"关都","rarity":"史诗","stats":{"hp":78,"atk":84,"def":78,"spa":109,"spd":85,"spe":100},"ability":"猛火","hidden":"太阳之力","egg":["—"],"steps":0,"evo":["火恐龙","喷火龙"],"forms":["关都形态"],"signature":"猛火"}'),
('007','杰尼龟','Squirtle','水','','普通','小龟宝可梦','0.5m','9.0kg','原本是杰尼龟军团的老大，戴着墨镜四处打抱不平。被小智收服后依旧照拂着那些小弟，遇险时缩入硬壳并顺势喷出强力水枪反击。','/pokemon/007.png','{"id":7,"number":"007","name":"杰尼龟","nameEn":"Squirtle","category":"水","category2":null,"level":"普通","classification":"小龟宝可梦","height":"0.5m","weight":"9.0kg","description":"原本是杰尼龟军团的老大，戴着墨镜四处打抱不平。被小智收服后依旧照拂着那些小弟，遇险时缩入硬壳并顺势喷出强力水枪反击。","image":"/pokemon/007.png","region":"关都","rarity":"普通","stats":{"hp":44,"atk":48,"def":65,"spa":50,"spd":64,"spe":43},"ability":"激流","hidden":"雨盘","egg":["—"],"steps":0,"evo":["杰尼龟","卡咪龟","水箭龟"],"forms":["关都形态"],"signature":"激流"}'),
('008','卡咪龟','Wartortle','水','','稀有','龟宝可梦','1m','22.5kg','「卡咪龟」是关都地区的龟宝可梦，水属性，特性为「激流」。','https://assets.pokemon.com/assets/cms2/img/pokedex/full/008.png','{"id":8,"number":"008","name":"卡咪龟","nameEn":"Wartortle","category":"水","category2":null,"level":"稀有","classification":"龟宝可梦","height":"1m","weight":"22.5kg","description":"「卡咪龟」是关都地区的龟宝可梦，水属性，特性为「激流」。","image":"https://assets.pokemon.com/assets/cms2/img/pokedex/full/008.png","region":"关都","rarity":"稀有","stats":{"hp":59,"atk":63,"def":80,"spa":65,"spd":80,"spe":58},"ability":"激流","hidden":"雨盘","egg":["—"],"steps":0,"evo":["杰尼龟","卡咪龟","水箭龟"],"forms":["关都形态"],"signature":"激流"}'),
('009','水箭龟','Blastoise','水','','史诗','甲壳宝可梦','1.6m','85.5kg','杰尼龟的最终进化型，龟壳上装有两门水炮，能喷射穿透岩石的高压水流。动画中常作为水系训练家的王牌登场，与小智的喷火龙形成经典对决。','/pokemon/009.png','{"id":9,"number":"009","name":"水箭龟","nameEn":"Blastoise","category":"水","category2":null,"level":"史诗","classification":"甲壳宝可梦","height":"1.6m","weight":"85.5kg","description":"杰尼龟的最终进化型，龟壳上装有两门水炮，能喷射穿透岩石的高压水流。动画中常作为水系训练家的王牌登场，与小智的喷火龙形成经典对决。","image":"/pokemon/009.png","region":"关都","rarity":"史诗","stats":{"hp":79,"atk":83,"def":100,"spa":85,"spd":105,"spe":78},"ability":"激流","hidden":"雨盘","egg":["—"],"steps":0,"evo":["卡咪龟","水箭龟"],"forms":["关都形态"],"signature":"激流"}'),
('010','绿毛虫','Caterpie','虫','','普通','虫宝宝宝可梦','0.3m','2.9kg','「绿毛虫」是关都地区的虫宝宝宝可梦，虫属性，特性为「鳞粉」。','https://assets.pokemon.com/assets/cms2/img/pokedex/full/010.png','{"id":10,"number":"010","name":"绿毛虫","nameEn":"Caterpie","category":"虫","category2":null,"level":"普通","classification":"虫宝宝宝可梦","height":"0.3m","weight":"2.9kg","description":"「绿毛虫」是关都地区的虫宝宝宝可梦，虫属性，特性为「鳞粉」。","image":"https://assets.pokemon.com/assets/cms2/img/pokedex/full/010.png","region":"关都","rarity":"普通","stats":{"hp":45,"atk":30,"def":35,"spa":20,"spd":20,"spe":45},"ability":"鳞粉","hidden":"逃跑","egg":["—"],"steps":0,"evo":["绿毛虫","铁甲蛹","巴大蝶"],"forms":["关都形态"],"signature":"鳞粉"}'),
('011','铁甲蛹','Metapod','虫','','普通','蛹宝可梦','0.7m','9.9kg','「铁甲蛹」是关都地区的蛹宝可梦，虫属性，特性为「蜕皮」。','https://assets.pokemon.com/assets/cms2/img/pokedex/full/011.png','{"id":11,"number":"011","name":"铁甲蛹","nameEn":"Metapod","category":"虫","category2":null,"level":"普通","classification":"蛹宝可梦","height":"0.7m","weight":"9.9kg","description":"「铁甲蛹」是关都地区的蛹宝可梦，虫属性，特性为「蜕皮」。","image":"https://assets.pokemon.com/assets/cms2/img/pokedex/full/011.png","region":"关都","rarity":"普通","stats":{"hp":50,"atk":20,"def":55,"spa":25,"spd":25,"spe":30},"ability":"蜕皮","hidden":"—","egg":["—"],"steps":0,"evo":["绿毛虫","铁甲蛹","巴大蝶"],"forms":["关都形态"],"signature":"蜕皮"}'),
('012','巴大蝶','Butterfree','虫','飞行','普通','蝶宝可梦','1.1m','32.0kg','小智的绿毛虫→铁甲蛹→巴大蝶，是他在动画里第一只亲手培育成熟的宝可梦。为了追寻粉色巴大蝶的爱情，它在关都的天空中与小智告别，成为无数观众的第一滴眼泪。','/pokemon/012.png','{"id":12,"number":"012","name":"巴大蝶","nameEn":"Butterfree","category":"虫","category2":"飞行","level":"普通","classification":"蝶宝可梦","height":"1.1m","weight":"32.0kg","description":"小智的绿毛虫→铁甲蛹→巴大蝶，是他在动画里第一只亲手培育成熟的宝可梦。为了追寻粉色巴大蝶的爱情，它在关都的天空中与小智告别，成为无数观众的第一滴眼泪。","image":"/pokemon/012.png","region":"关都","rarity":"普通","stats":{"hp":60,"atk":45,"def":50,"spa":90,"spd":80,"spe":70},"ability":"复眼","hidden":"有色眼镜","egg":["—"],"steps":0,"evo":["铁甲蛹","巴大蝶"],"forms":["关都形态"],"signature":"复眼"}'),
('013','独角虫','Weedle','虫','毒','普通','毛毛虫宝可梦','0.3m','3.2kg','「独角虫」是关都地区的毛毛虫宝可梦，虫／毒属性，特性为「鳞粉」。','https://assets.pokemon.com/assets/cms2/img/pokedex/full/013.png','{"id":13,"number":"013","name":"独角虫","nameEn":"Weedle","category":"虫","category2":"毒","level":"普通","classification":"毛毛虫宝可梦","height":"0.3m","weight":"3.2kg","description":"「独角虫」是关都地区的毛毛虫宝可梦，虫／毒属性，特性为「鳞粉」。","image":"https://assets.pokemon.com/assets/cms2/img/pokedex/full/013.png","region":"关都","rarity":"普通","stats":{"hp":40,"atk":35,"def":30,"spa":20,"spd":20,"spe":50},"ability":"鳞粉","hidden":"逃跑","egg":["—"],"steps":0,"evo":["独角虫","铁壳蛹","大针蜂"],"forms":["关都形态"],"signature":"鳞粉"}'),
