('015','大针蜂','Beedrill','虫','毒','普通','毒蜂宝可梦','1m','29.5kg','「大针蜂」是关都地区的毒蜂宝可梦，虫／毒属性，特性为「虫之预感」。','https://assets.pokemon.com/assets/cms2/img/pokedex/full/015.png','{"id":15,"number":"015","name":"大针蜂","nameEn":"Beedrill","category":"虫","category2":"毒","level":"普通","classification":"毒蜂宝可梦","height":"1m","weight":"29.5kg","description":"「大针蜂」是关都地区的毒蜂宝可梦，虫／毒属性，特性为「虫之预感」。","image":"https://assets.pokemon.com/assets/cms2/img/pokedex/full/015.png","region":"关都","rarity":"普通","stats":{"hp":65,"atk":90,"def":40,"spa":45,"spd":80,"spe":75},"ability":"虫之预感","hidden":"狙击手","egg":["—"],"steps":0,"evo":["铁壳蛹","大针蜂"],"forms":["关都形态"],"signature":"虫之预感"}'),
('016','波波','Pidgey','一般','飞行','普通','小鸟宝可梦','0.3m','1.8kg','「波波」是关都地区的小鸟宝可梦，一般／飞行属性，特性为「锐利目光」。','https://assets.pokemon.com/assets/cms2/img/pokedex/full/016.png','{"id":16,"number":"016","name":"波波","nameEn":"Pidgey","category":"一般","category2":"飞行","level":"普通","classification":"小鸟宝可梦","height":"0.3m","weight":"1.8kg","description":"「波波」是关都地区的小鸟宝可梦，一般／飞行属性，特性为「锐利目光」。","image":"https://assets.pokemon.com/assets/cms2/img/pokedex/full/016.png","region":"关都","rarity":"普通","stats":{"hp":40,"atk":45,"def":40,"spa":35,"spd":35,"spe":56},"ability":"锐利目光","hidden":"健壮胸肌","egg":["—"],"steps":0,"evo":["波波","比比鸟","大比鸟"],"forms":["关都形态"],"signature":"锐利目光"}'),
('017','比比鸟','Pidgeotto','一般','飞行','普通','鸟宝可梦','1.1m','30kg','「比比鸟」是关都地区的鸟宝可梦，一般／飞行属性，特性为「锐利目光」。','https://assets.pokemon.com/assets/cms2/img/pokedex/full/017.png','{"id":17,"number":"017","name":"比比鸟","nameEn":"Pidgeotto","category":"一般","category2":"飞行","level":"普通","classification":"鸟宝可梦","height":"1.1m","weight":"30kg","description":"「比比鸟」是关都地区的鸟宝可梦，一般／飞行属性，特性为「锐利目光」。","image":"https://assets.pokemon.com/assets/cms2/img/pokedex/full/017.png","region":"关都","rarity":"普通","stats":{"hp":63,"atk":60,"def":55,"spa":50,"spd":50,"spe":71},"ability":"锐利目光","hidden":"健壮胸肌","egg":["—"],"steps":0,"evo":["波波","比比鸟","大比鸟"],"forms":["关都形态"],"signature":"锐利目光"}'),
('018','大比鸟','Pidgeot','一般','飞行','稀有','鸟宝可梦','1.5m','39.5kg','小智的比比鸟最终进化型。为守护同伴的大比鸟群而留在森林，临别时约定「等我办完事就回来接你」，成为动画里最令人牵挂的约定之一。','/pokemon/018.png','{"id":18,"number":"018","name":"大比鸟","nameEn":"Pidgeot","category":"一般","category2":"飞行","level":"稀有","classification":"鸟宝可梦","height":"1.5m","weight":"39.5kg","description":"小智的比比鸟最终进化型。为守护同伴的大比鸟群而留在森林，临别时约定「等我办完事就回来接你」，成为动画里最令人牵挂的约定之一。","image":"/pokemon/018.png","region":"关都","rarity":"稀有","stats":{"hp":83,"atk":80,"def":75,"spa":70,"spd":70,"spe":101},"ability":"锐利目光","hidden":"健壮胸肌","egg":["—"],"steps":0,"evo":["比比鸟","大比鸟"],"forms":["关都形态"],"signature":"锐利目光"}'),
