('025','皮卡丘','Pikachu','电','','普通','鼠宝可梦','0.4m','6.0kg','小智最初的伙伴。出发那天迟到的少年只领到这只不肯进精灵球的皮卡丘；被烈雀群围攻时它仍拼死放出电击护住小智，羁绊自此开始。它拒绝用雷之石进化，坚持以原本的自己战斗到底。','/pokemon/025.png','{"id":25,"number":"025","name":"皮卡丘","nameEn":"Pikachu","category":"电","category2":null,"level":"普通","classification":"鼠宝可梦","height":"0.4m","weight":"6.0kg","description":"小智最初的伙伴。出发那天迟到的少年只领到这只不肯进精灵球的皮卡丘；被烈雀群围攻时它仍拼死放出电击护住小智，羁绊自此开始。它拒绝用雷之石进化，坚持以原本的自己战斗到底。","image":"/pokemon/025.png","region":"关都","rarity":"普通","stats":{"hp":35,"atk":55,"def":40,"spa":50,"spd":50,"spe":90},"ability":"静电","hidden":"避雷针","egg":["—"],"steps":0,"evo":["皮丘","皮卡丘","雷丘","雷丘（阿罗拉形态）"],"forms":["关都形态"],"signature":"静电"}'),
('026','雷丘','Raichu','电','','稀有','鼠宝可梦','0.8m','30.0kg','皮卡丘的进化型，尾巴像避雷针般立起，能将储存的电力一次释放。枯叶道馆馆主马奇的雷丘、以及皮卡丘短暂的进化形态，都是动画中令人难忘的存在。','/pokemon/026.png','{"id":26,"number":"026","name":"雷丘","nameEn":"Raichu","category":"电","category2":null,"level":"稀有","classification":"鼠宝可梦","height":"0.8m","weight":"30.0kg","description":"皮卡丘的进化型，尾巴像避雷针般立起，能将储存的电力一次释放。枯叶道馆馆主马奇的雷丘、以及皮卡丘短暂的进化形态，都是动画中令人难忘的存在。","image":"/pokemon/026.png","region":"关都","rarity":"稀有","stats":{"hp":60,"atk":90,"def":55,"spa":90,"spd":80,"spe":110},"ability":"静电","hidden":"避雷针","egg":["—"],"steps":0,"evo":["皮卡丘","雷丘"],"forms":["关都形态"],"signature":"静电"}'),
