('149','快龙','Dragonite','龙','飞行','史诗','龙宝可梦','2.2m','210.0kg','动画中以「救难的宝可梦」形象出现，曾载着迷路者飞渡大海。小智在旅途篇收服的哈克龙进化成快龙，成为世界冠军赛上的重要战力。','/pokemon/149.png','{"id":149,"number":"149","name":"快龙","nameEn":"Dragonite","category":"龙","category2":"飞行","level":"史诗","classification":"龙宝可梦","height":"2.2m","weight":"210.0kg","description":"动画中以「救难的宝可梦」形象出现，曾载着迷路者飞渡大海。小智在旅途篇收服的哈克龙进化成快龙，成为世界冠军赛上的重要战力。","image":"/pokemon/149.png","region":"关都","rarity":"史诗","stats":{"hp":91,"atk":134,"def":95,"spa":100,"spd":100,"spe":80},"ability":"精神力","hidden":"多重鳞片","egg":["—"],"steps":0,"evo":["哈克龙","快龙"],"forms":["关都形态"],"signature":"精神力"}'),
('150','超梦','Mewtwo','超能力','','传说','基因宝可梦','2.0m','122.0kg','由梦幻基因创造的人造宝可梦，拥有压倒性的超能力，长期追问「我为何而存在」。剧场版《超梦的逆袭》中与小智的相遇，让它第一次理解了羁绊的意义。','/pokemon/150.png','{"id":150,"number":"150","name":"超梦","nameEn":"Mewtwo","category":"超能力","category2":null,"level":"传说","classification":"基因宝可梦","height":"2.0m","weight":"122.0kg","description":"由梦幻基因创造的人造宝可梦，拥有压倒性的超能力，长期追问「我为何而存在」。剧场版《超梦的逆袭》中与小智的相遇，让它第一次理解了羁绊的意义。","image":"/pokemon/150.png","region":"关都","rarity":"神兽","stats":{"hp":106,"atk":110,"def":90,"spa":154,"spd":90,"spe":130},"ability":"压迫感","hidden":"紧张感","egg":["—"],"steps":0,"evo":["超梦"],"forms":["关都形态"],"signature":"压迫感"}'),
('151','梦幻','Mew','超能力','','传说','新种宝可梦','0.4m','4.0kg','被认为已灭绝、实则隐居世外的幻之宝可梦，是所有宝可梦基因的源头。《超梦的逆袭》《梦幻与波导的勇者》中都以旁观者的姿态注视着人类的羁绊。','/pokemon/151.png','{"id":151,"number":"151","name":"梦幻","nameEn":"Mew","category":"超能力","category2":null,"level":"传说","classification":"新种宝可梦","height":"0.4m","weight":"4.0kg","description":"被认为已灭绝、实则隐居世外的幻之宝可梦，是所有宝可梦基因的源头。《超梦的逆袭》《梦幻与波导的勇者》中都以旁观者的姿态注视着人类的羁绊。","image":"/pokemon/151.png","region":"关都","rarity":"幻兽","stats":{"hp":100,"atk":100,"def":100,"spa":100,"spd":100,"spe":100},"ability":"同步","hidden":"—","egg":["—"],"steps":0,"evo":["梦幻"],"forms":["关都形态"],"signature":"同步"}'),
